std::span<DbcTableMeta const> GetVanillaDbcTables()
{
    return g_dbcTables;
}

DbcTableMeta const* FindVanillaDbcTable(std::string_view name)
{
    for (DbcTableMeta const& table : g_dbcTables)
    {
        if (name.size() == std::strlen(table.name) &&
            std::equal(name.begin(), name.end(), table.name, [](char a, char b)
            { return std::tolower(static_cast<unsigned char>(a)) == std::tolower(static_cast<unsigned char>(b)); }))
            return &table;
    }
    return nullptr;
}
